using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using Object=UnityEngine.Object;
public static class CaptureRolePrefabPoses {
 public static object Main(string folder,string ids){if(!EditorApplication.isPlaying)throw new Exception("Play required");Directory.CreateDirectory(folder);var stage=new GameObject("Temporary role art review stage");stage.transform.position=new Vector3(10000,0,10000);var rows=new List<object>();var rt=new RenderTexture(768,768,24);try{var cg=new GameObject("Temporary role review camera");cg.transform.SetParent(stage.transform,false);var camera=cg.AddComponent<Camera>();camera.enabled=false;camera.cullingMask=1<<31;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.32f,.35f,.38f);camera.orthographic=true;camera.orthographicSize=1.45f;camera.nearClipPlane=.1f;camera.farClipPlane=25;camera.targetTexture=rt;cg.transform.localPosition=new Vector3(2.9f,2.05f,5);cg.transform.LookAt(stage.transform.position+Vector3.up*1.05f);var light=new GameObject("Review key light");light.transform.SetParent(stage.transform,false);light.transform.localRotation=Quaternion.Euler(40,-30,0);var l=light.AddComponent<Light>();l.type=LightType.Directional;l.intensity=1.25f;l.cullingMask=1<<31;
  foreach(var id in ids.Split(',')){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/ShooterSurvival/Models/Chapters/Chapters45/DetailedCharacters20261003/"+id+"/"+id+".prefab");var actor=Object.Instantiate(prefab,stage.transform);actor.transform.localPosition=Vector3.zero;foreach(var t in actor.GetComponentsInChildren<Transform>(true))t.gameObject.layer=31;var animator=actor.GetComponentInChildren<Animator>();animator.cullingMode=AnimatorCullingMode.AlwaysAnimate;animator.applyRootMotion=false;foreach(var state in new[]{"idle","walk","attack_once","die","dribble"}){if(!animator.HasState(0,Animator.StringToHash(state)))continue;foreach(float phase in new[]{0f,.25f,.5f,.75f}){animator.Play(state,0,phase);animator.Update(0);camera.Render();var previous=RenderTexture.active;RenderTexture.active=rt;var png=new Texture2D(768,768,TextureFormat.RGB24,false);png.ReadPixels(new Rect(0,0,768,768),0,0);png.Apply();var file=id+"-"+state+"-"+phase.ToString("F2",System.Globalization.CultureInfo.InvariantCulture)+".png";File.WriteAllBytes(Path.Combine(folder,file),png.EncodeToPNG());Object.DestroyImmediate(png);RenderTexture.active=previous;rows.Add(new{id,state,phase,file});}}Object.DestroyImmediate(actor);}
 }finally{Object.DestroyImmediate(stage);rt.Release();Object.DestroyImmediate(rt);}File.WriteAllText(Path.Combine(folder,"conditions.txt"),"Actual Unity Play, isolated temporary stage, original own Animator/controller evaluated at normalized phases; not ordinary gameplay proof.");return new{folder,frames=rows};}
}
